//! Workspace tasks. `cargo xtask tokens [--check]` turns `design/tokens.json` into the Slint `Tokens` global
//! (`crates/ui/ui/tokens.slint`) and one SVG per icon (`crates/ui/ui/icons/`). With `--check` it writes nothing and
//! fails when the generated files are out of date.

#![forbid(unsafe_code)]

use serde_json::{Map, Value};
use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

const NEWLINE: &str = "\r\n";

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let result = match args.first().map(String::as_str) {
        Some("tokens") => tokens(args.iter().any(|a| a == "--check")),
        _ => Err("usage: cargo xtask tokens [--check]".to_owned()),
    };
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("{message}");
            ExitCode::FAILURE
        }
    }
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn tokens(check: bool) -> Result<(), String> {
    let root = workspace_root();
    let source = root.join("design/tokens.json");
    let json: Value = serde_json::from_str(&fs::read_to_string(&source).map_err(|e| format!("{source:?}: {e}"))?).map_err(|e| format!("{source:?}: {e}"))?;

    let ui_dir = root.join("crates/ui/ui");
    let mut outputs = vec![(ui_dir.join("tokens.slint"), slint_tokens(&json)?)];
    for (name, icon) in section(&json, "icons")? {
        let path = str_field(icon, "path", name)?;
        outputs.push((ui_dir.join("icons").join(format!("{}.svg", icon_file(name))), svg(name, path)?));
    }
    for (name, gradient) in radial_gradients(&json) {
        outputs.push((ui_dir.join("gradients").join(format!("{}.svg", kebab(name))), radial_svg(gradient, name)?));
    }

    let stale: Vec<&PathBuf> = outputs
        .iter()
        .filter(|(path, text)| fs::read_to_string(path).ok().as_deref() != Some(text))
        .map(|(path, _)| path)
        .collect();
    if check {
        if stale.is_empty() {
            return Ok(());
        }
        return Err(format!("generated tokens are out of date, run `cargo xtask tokens`: {stale:?}"));
    }
    fs::create_dir_all(ui_dir.join("icons")).map_err(|e| e.to_string())?;
    fs::create_dir_all(ui_dir.join("gradients")).map_err(|e| e.to_string())?;
    for (path, text) in &outputs {
        fs::write(path, text).map_err(|e| format!("{path:?}: {e}"))?;
    }
    println!("wrote {} files ({} changed)", outputs.len(), stale.len());
    Ok(())
}

fn slint_tokens(json: &Value) -> Result<String, String> {
    let meta = section(json, "meta")?;
    let mut out = Lines::default();
    out.line("// Generated by `cargo xtask tokens` from design/tokens.json. Do not edit.");
    out.line(&format!(
        "// Source: {} at {}.",
        meta.get("source").and_then(Value::as_str).unwrap_or("?"),
        meta.get("commit").and_then(Value::as_str).unwrap_or("?")
    ));
    out.blank();

    for (_, font) in section(json, "fonts")? {
        for file in font.get("files").and_then(Value::as_array).into_iter().flatten() {
            let file = file.as_str().ok_or("font file is not a string")?;
            out.line(&format!("import \"../../../design/{file}\";"));
        }
    }
    out.blank();
    out.line("// A Thickness from the token source: one inset per side.");
    out.line("export struct Inset { left: length, top: length, right: length, bottom: length }");
    out.blank();
    out.line("export global Tokens {");
    out.line("    // Set from Rust: Windows high contrast and the \"Animation effects\" setting.");
    out.line("    in-out property <bool> high-contrast: false;");
    out.line("    in-out property <bool> motion: true;");

    let mut notes = Notes::default();
    for (name, font) in section(json, "fonts")? {
        notes.emit(&mut out, font);
        let family = str_field(font, "family", name)?;
        out.prop("string", name, &format!("\"{family}\""));
    }
    for (name, weight) in section(json, "fontWeights")? {
        notes.emit(&mut out, weight);
        out.prop("int", name, &number(weight, name)?.to_string());
    }
    for (name, color) in section(json, "colors")? {
        notes.emit(&mut out, color);
        out.prop("color", name, str_field(color, "value", name)?);
    }
    let brushes = section(json, "brushes")?;
    for (name, brush) in brushes {
        notes.emit(&mut out, brush);
        let mut value = match brush.get("color").and_then(Value::as_str) {
            Some(color) => kebab(color),
            None => str_field(brush, "value", name)?.to_owned(),
        };
        // A role brush with a `HighContrast<Role>` sibling swaps to it under Windows high contrast
        // (spec/shell-and-settings.md §7).
        let contrast = format!("HighContrast{name}");
        if brushes.contains_key(&contrast) {
            value = format!("high-contrast ? {} : {value}", kebab(&contrast));
        }
        out.prop("brush", name, &value);
    }
    for (name, gradient) in section(json, "gradients")? {
        notes.emit(&mut out, gradient);
        out.prop("brush", name, &linear_gradient(gradient, name)?);
    }
    // Slint's radial gradients are centred circles, so an off-centre or elliptical one is an SVG of the whole ellipse,
    // placed by its bounds over a ground of its last stop.
    for (name, gradient) in radial_gradients(json) {
        notes.emit(&mut out, gradient);
        let ellipse = Ellipse::read(gradient, name)?;
        let stops = radial_stops(gradient, name)?;
        let ground = stops.last().map(|(_, color)| color.clone()).ok_or(format!("{name}: no stops"))?;
        out.prop("image", &format!("{name}Image"), &format!("@image-url(\"gradients/{}.svg\")", kebab(name)));
        out.prop("length", &format!("{name}X"), &format!("{}px", fmt(ellipse.cx - ellipse.rx)));
        out.prop("length", &format!("{name}Y"), &format!("{}px", fmt(ellipse.cy - ellipse.ry)));
        out.prop("length", &format!("{name}Width"), &format!("{}px", fmt(2.0 * ellipse.rx)));
        out.prop("length", &format!("{name}Height"), &format!("{}px", fmt(2.0 * ellipse.ry)));
        out.prop("brush", &format!("{name}Ground"), &ground);
    }
    for (name, value) in section(json, "numbers")? {
        notes.emit(&mut out, value);
        let n = number(value, name)?;
        let (ty, literal) = match number_kind(name) {
            NumberKind::Int => ("int", format!("{}", n as i64)),
            NumberKind::Float => ("float", fmt(n)),
            NumberKind::Length => ("length", format!("{}px", fmt(n))),
        };
        out.prop(ty, name, &literal);
    }
    for (name, thickness) in section(json, "thicknesses")? {
        notes.emit(&mut out, thickness);
        let v = thickness.get("value").ok_or(format!("{name}: no value"))?;
        let side = |s: &str| v.get(s).and_then(Value::as_f64).map(fmt).ok_or(format!("{name}: no {s}"));
        let literal = format!(
            "{{ left: {}px, top: {}px, right: {}px, bottom: {}px }}",
            side("left")?,
            side("top")?,
            side("right")?,
            side("bottom")?
        );
        out.prop("Inset", name, &literal);
    }
    for section_name in ["radii", "gridLengths"] {
        for (name, value) in section(json, section_name)? {
            notes.emit(&mut out, value);
            out.prop("length", name, &format!("{}px", fmt(number(value, name)?)));
        }
    }
    for (name, duration) in section(json, "durations")? {
        notes.emit(&mut out, duration);
        let ms = duration.get("ms").and_then(Value::as_f64).ok_or(format!("{name}: no ms"))?;
        out.prop("duration", name, &format!("{}ms", fmt(ms)));
    }
    for (name, icon) in section(json, "icons")? {
        notes.emit(&mut out, icon);
        out.prop("image", name, &format!("@image-url(\"icons/{}.svg\")", icon_file(name)));
    }
    out.line("}");
    Ok(out.text)
}

enum NumberKind {
    Int,
    Float,
    Length,
}

/// `numbers` mixes lengths with counts and ratios; the token name says which.
fn number_kind(name: &str) -> NumberKind {
    if ["MaxLines", "Limit", "FramesPerSecond", "MaxColumns"].iter().any(|s| name.ends_with(s)) {
        NumberKind::Int
    } else if ["Opacity", "Share", "Scale", "Level", "Factor", "Step", "Seconds", "Area", "Climb", "ClearBand", "Handover"]
        .iter()
        .any(|s| name.contains(s))
    {
        NumberKind::Float
    } else {
        NumberKind::Length
    }
}

fn linear_gradient(gradient: &Value, name: &str) -> Result<String, String> {
    let point = |key: &str| -> Result<(f64, f64), String> {
        let text = str_field(gradient, key, name)?;
        let mut parts = text.split(',').map(|p| p.trim().trim_end_matches('%').parse::<f64>());
        match (parts.next(), parts.next()) {
            (Some(Ok(x)), Some(Ok(y))) => Ok((x, y)),
            _ => Err(format!("{name}: cannot read {key} {text:?}")),
        }
    };
    let (start, end) = (point("start")?, point("end")?);
    // CSS angles: 0deg points up, 90deg points right; y grows downwards.
    let angle = (end.0 - start.0).atan2(start.1 - end.1).to_degrees().rem_euclid(360.0);
    let mut stops = Vec::new();
    for stop in gradient.get("stops").and_then(Value::as_array).ok_or(format!("{name}: no stops"))? {
        let offset = stop.get("offset").and_then(Value::as_f64).ok_or(format!("{name}: stop without offset"))?;
        let color = match stop.get("color").and_then(Value::as_str) {
            Some(color) => kebab(color),
            None => str_field(stop, "value", name)?.to_owned(),
        };
        stops.push(format!("{color} {}%", fmt(offset * 100.0)));
    }
    Ok(format!("@linear-gradient({}deg, {})", fmt(angle), stops.join(", ")))
}

fn radial_gradients(json: &Value) -> impl Iterator<Item = (&String, &Value)> {
    json.get("radialGradients").and_then(Value::as_object).into_iter().flatten()
}

/// A radial gradient's ellipse in absolute pixels (Avalonia's `Center`, `RadiusX`, `RadiusY`).
struct Ellipse {
    cx: f64,
    cy: f64,
    rx: f64,
    ry: f64,
}

impl Ellipse {
    fn read(gradient: &Value, name: &str) -> Result<Ellipse, String> {
        let center = str_field(gradient, "center", name)?;
        if center.contains('%') {
            return Err(format!("{name}: a relative centre ({center}) is not supported"));
        }
        let mut parts = center.split(',').map(|p| p.trim().parse::<f64>());
        let (Some(Ok(cx)), Some(Ok(cy))) = (parts.next(), parts.next()) else {
            return Err(format!("{name}: cannot read centre {center:?}"));
        };
        Ok(Ellipse {
            cx,
            cy,
            rx: number_field(gradient, "radiusX", name)?,
            ry: number_field(gradient, "radiusY", name)?,
        })
    }
}

fn number_field(token: &Value, field: &str, name: &str) -> Result<f64, String> {
    token.get(field).and_then(Value::as_f64).ok_or(format!("{name}: no `{field}` number"))
}

/// Offsets and colours: the token's name for a named colour (for `tokens.slint`), with its hex value beside it.
fn radial_stops(gradient: &Value, name: &str) -> Result<Vec<(f64, String)>, String> {
    let mut stops = Vec::new();
    for stop in gradient.get("stops").and_then(Value::as_array).ok_or(format!("{name}: no stops"))? {
        let offset = stop.get("offset").and_then(Value::as_f64).ok_or(format!("{name}: stop without offset"))?;
        let color = match stop.get("color").and_then(Value::as_str) {
            Some(color) => kebab(color),
            None => str_field(stop, "value", name)?.to_owned(),
        };
        stops.push((offset, color));
    }
    Ok(stops)
}

/// The whole ellipse as an SVG the size of its bounds: a circle gradient squeezed to the ellipse.
fn radial_svg(gradient: &Value, name: &str) -> Result<String, String> {
    let e = Ellipse::read(gradient, name)?;
    let mut stops = String::new();
    for stop in gradient.get("stops").and_then(Value::as_array).ok_or(format!("{name}: no stops"))? {
        let offset = stop.get("offset").and_then(Value::as_f64).ok_or(format!("{name}: stop without offset"))?;
        let value = str_field(stop, "value", name)?;
        let (rgb, alpha) = if value.len() == 9 {
            (&value[..7], u8::from_str_radix(&value[7..], 16).map_err(|e| e.to_string())?)
        } else {
            (value, 255)
        };
        let _ = write!(
            stops,
            "<stop offset=\"{}\" stop-color=\"{rgb}\" stop-opacity=\"{}\"/>",
            fmt(offset),
            fmt(f64::from(alpha) / 255.0)
        );
    }
    Ok(format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{w}\" height=\"{h}\" viewBox=\"0 0 {w} {h}\"><defs><radialGradient id=\"g\" gradientUnits=\"userSpaceOnUse\" cx=\"{rx}\" cy=\"{ry}\" r=\"{rx}\" gradientTransform=\"translate(0 {ry}) scale(1 {k}) translate(0 -{ry})\">{stops}</radialGradient></defs><rect width=\"{w}\" height=\"{h}\" fill=\"url(#g)\"/></svg>{NEWLINE}",
        w = fmt(2.0 * e.rx),
        h = fmt(2.0 * e.ry),
        rx = fmt(e.rx),
        ry = fmt(e.ry),
        k = fmt(e.ry / e.rx),
    ))
}

/// One icon as an SVG whose view box is the square round the path's own bounds, centred, so it fills a square box as
/// Avalonia's `PathIcon` stretches its geometry (uniformly, centred). A square box also keeps the software renderer from
/// stretching a not-quite-square icon past its box, which cut the foot off the small warning mark.
fn svg(name: &str, path: &str) -> Result<String, String> {
    use kurbo::Shape as _;
    let bounds = kurbo::BezPath::from_svg(path).map_err(|e| format!("{name}: {e}"))?.bounding_box();
    let side = bounds.width().max(bounds.height());
    Ok(format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{w}\" height=\"{w}\" viewBox=\"{x} {y} {w} {w}\"><path d=\"{path}\" fill=\"#000\"/></svg>{NEWLINE}",
        x = fmt(bounds.x0 - (side - bounds.width()) / 2.0),
        y = fmt(bounds.y0 - (side - bounds.height()) / 2.0),
        w = fmt(side),
    ))
}

#[derive(Default)]
struct Lines {
    text: String,
}

impl Lines {
    fn line(&mut self, line: &str) {
        self.text.push_str(line);
        self.text.push_str(NEWLINE);
    }

    fn blank(&mut self) {
        self.text.push_str(NEWLINE);
    }

    fn prop(&mut self, ty: &str, name: &str, value: &str) {
        let _ = write!(self.text, "    out property <{ty}> {}: {value};{NEWLINE}", kebab(name));
    }
}

/// Writes a token's note as a comment when it differs from the previous one, since one note often covers a group.
#[derive(Default)]
struct Notes {
    last: Option<String>,
}

impl Notes {
    fn emit(&mut self, out: &mut Lines, token: &Value) {
        let note = token.get("note").and_then(Value::as_str).map(|n| n.split_whitespace().collect::<Vec<_>>().join(" "));
        if note.is_some() && note != self.last {
            out.blank();
            out.line(&format!("    // {}", note.as_deref().unwrap_or_default()));
        }
        if note.is_some() {
            self.last = note;
        }
    }
}

fn section<'a>(json: &'a Value, name: &str) -> Result<&'a Map<String, Value>, String> {
    json.get(name).and_then(Value::as_object).ok_or(format!("tokens.json has no `{name}` object"))
}

fn str_field<'a>(token: &'a Value, field: &str, name: &str) -> Result<&'a str, String> {
    token.get(field).and_then(Value::as_str).ok_or(format!("{name}: no `{field}` string"))
}

fn number(token: &Value, name: &str) -> Result<f64, String> {
    token.get("value").and_then(Value::as_f64).ok_or(format!("{name}: no numeric `value`"))
}

fn fmt(n: f64) -> String {
    let text = format!("{n:.4}");
    text.trim_end_matches('0').trim_end_matches('.').to_owned()
}

/// `GroundColor` -> `ground-color`, `Space10` -> `space-10`.
fn kebab(name: &str) -> String {
    let chars: Vec<char> = name.chars().collect();
    let mut out = String::new();
    for (i, &c) in chars.iter().enumerate() {
        if i > 0 {
            let prev = chars[i - 1];
            let next_lower = chars.get(i + 1).is_some_and(|n| n.is_lowercase());
            let boundary = (c.is_uppercase() && (prev.is_lowercase() || prev.is_ascii_digit()))
                || (c.is_uppercase() && prev.is_uppercase() && next_lower)
                || (c.is_ascii_digit() && prev.is_alphabetic());
            if boundary {
                out.push('-');
            }
        }
        out.extend(c.to_lowercase());
    }
    out
}

fn icon_file(name: &str) -> String {
    kebab(name.strip_prefix("Icon").unwrap_or(name))
}
